record FieldError(String field, String message, Object rejectedValue) {}

List<FieldError> validateUser(String email, int age, String password) {
    List<FieldError> errors = new ArrayList<>();
    if (email == null || !email.contains("@")) {
        errors.add(new FieldError("email", "Niepoprawny format email", email));
    }
    if (age < 0) {
        errors.add(new FieldError("age", "Wiek nie moze byc ujemny", age));
    }
    if (password == null || password.length() < 8) {
        errors.add(new FieldError("password", "Haslo musi miec co najmniej 8 znakow", null));
    }
    return errors; // WSZYSTKIE naruszenia naraz, nie tylko pierwsze napotkane
}

record ValidationProblemDetails(
    String type, String title, int status, String detail, String instance,
    List<FieldError> errors
) {}

ValidationProblemDetails buildValidationError(List<FieldError> violations, String instance) {
    return new ValidationProblemDetails(
        "https://example.com/problems/validation-error",
        "Bledne dane wejsciowe", 422,
        "Zadanie zawiera " + violations.size() + " nieprawidlowych pol",
        instance, violations
    );
}
